from decimal import Decimal, getcontext, ROUND_HALF_UP, ROUND_DOWN, InvalidOperation

getcontext().prec = 80

_Q2 = Decimal("0.01")

# Valores por defecto tomados de 02_parametros.sql (LS_PARAMETROS.valor_numerico)
_DEFAULT_PARAMS = {
    "DIAS_MAX_DENUNCIA": Decimal("30"),
    "DIAS_MAX_DENUNCIA_VIDA": Decimal("365"),
    "DEDUCIBLE_MINIMO": Decimal("100"),
    "PCT_DESCUENTO_DED_VIP": Decimal("50"),
    "TOLERANCIA_MORA_VIP": Decimal("500"),
    "MAX_SINIESTROS_ANUAL": Decimal("3"),
    "PCT_PENALIZACION_SINIEST": Decimal("10"),
    "UMBRAL_RETENCION": Decimal("10000"),
    "TASA_RETENCION": Decimal("2"),
    "TOPE_AUTO_APROBACION": Decimal("50000"),
    "DIAS_ALERTA_FRAUDE": Decimal("15"),
    "PCT_ALERTA_FRAUDE": Decimal("80"),
    "FACTOR_INFLACION": Decimal("1.035"),
    "TASA_IVA": Decimal("19"),
    "VERSION_MOTOR": None,
}


class _LegacyError(Exception):
    def __init__(self, code):
        Exception.__init__(self, code)
        self.code = code


# ---------------------------------------------------------------------------
# Utilidades de conversión
# ---------------------------------------------------------------------------
def _s(v):
    if v is None:
        return ""
    return str(v).strip()


def _dec(v):
    t = _s(v)
    if t == "" or t.upper() == "NULL" or t.upper() == "NONE":
        return None
    try:
        return Decimal(t.replace(",", "") if t.count(",") and t.count(".") else t.replace(",", "."))
    except InvalidOperation:
        return None


def _bool(v):
    if isinstance(v, bool):
        return v
    return _s(v).upper() in ("TRUE", "1", "S", "SI", "Y", "YES", "T", "V", "VERDADERO")


def _day_number(v):
    t = _s(v)
    if len(t) >= 8 and t[:8].isdigit():
        y, m, d = int(t[0:4]), int(t[4:6]), int(t[6:8])
    else:
        t = t[:10]
        y, m, d = int(t[0:4]), int(t[5:7]), int(t[8:10])
    if m <= 2:
        y -= 1
    era = y // 400
    yoe = y - era * 400
    mp = (m + 9) % 12
    doy = (153 * mp + 2) // 5 + d - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe - 719468


def _parse_params(raw):
    params = dict(_DEFAULT_PARAMS)
    if raw is None:
        return params
    if isinstance(raw, dict):
        for k, v in raw.items():
            params[_s(k).upper()] = _dec(v)
        return params
    text = _s(raw)
    if text == "":
        return params
    text = text.strip().strip("{}[]")
    for sep in (";", "\n", "\r", "&"):
        text = text.replace(sep, ",")
    for item in text.split(","):
        item = item.strip()
        if item == "":
            continue
        if ":" in item:
            k, v = item.split(":", 1)
        elif "=" in item:
            k, v = item.split("=", 1)
        else:
            continue
        k = k.strip().strip("\"'").strip().upper()
        v = v.strip().strip("\"'").strip()
        if k == "":
            continue
        params[k] = _dec(v)
    return params


# ---------------------------------------------------------------------------
# Aritmética con semántica NULL de Oracle
# ---------------------------------------------------------------------------
def _add(a, b):
    return None if a is None or b is None else a + b


def _sub(a, b):
    return None if a is None or b is None else a - b


def _mul(a, b):
    return None if a is None or b is None else a * b


def _div(a, b):
    return None if a is None or b is None else a / b


def _round2(a):
    return None if a is None else a.quantize(_Q2, rounding=ROUND_HALF_UP)


def _gt(a, b):
    return a is not None and b is not None and a > b


def _ge(a, b):
    return a is not None and b is not None and a >= b


def _lt(a, b):
    return a is not None and b is not None and a < b


def _le(a, b):
    return a is not None and b is not None and a <= b


def _store_14_2(a):
    """Asignación a variable NUMBER(14,2): redondeo a 2 decimales; overflow => ORA-06502."""
    if a is None:
        return None
    q = a.quantize(_Q2, rounding=ROUND_HALF_UP)
    if abs(q) >= Decimal(10) ** 12:
        raise _LegacyError("06502")
    return q


def _fmt2(a):
    if a is None:
        return ""
    q = a.quantize(_Q2, rounding=ROUND_HALF_UP)
    if q == 0:
        q = Decimal("0.00")
    return format(q, "f")


def _add_obs(obs, mark):
    if obs is None or obs == "":
        return mark
    return obs + ";" + mark


# ---------------------------------------------------------------------------
# Implementación de referencia de PR_LIQUIDAR_SINIESTRO
# ---------------------------------------------------------------------------
def run(inp: dict) -> dict:
    out = {
        "base_amount": "0.00",
        "deductible_amount": "0.00",
        "covered_amount": "0.00",
        "withholding_amount": "0.00",
        "net_amount": "0.00",
        "liquidation_status": "",
        "reason_code": "",
        "observations": "",
        "claim_new_status": "",
        "error_code": "",
    }
    try:
        res = _liquidar(inp)
        out.update(res)
    except _LegacyError as e:
        out["error_code"] = e.code
    except (ValueError, IndexError, InvalidOperation, TypeError):
        out["error_code"] = "INVALID_INPUT"
    return out


def _liquidar(inp):
    params = _parse_params(inp.get("parameters"))

    def p(code):
        if code not in params:
            raise _LegacyError("20010")
        return params[code]

    claim_status = _s(inp.get("claim_status")).upper()
    if claim_status != "REGISTRADO":
        raise _LegacyError("20001")

    claimed = _dec(inp.get("claimed_amount"))
    occ = _day_number(inp.get("occurrence_date"))
    rep = _day_number(inp.get("report_date"))
    pol_start = _day_number(inp.get("policy_start_date"))
    pol_end = _day_number(inp.get("policy_end_date"))
    policy_status = _s(inp.get("policy_status")).upper()
    ramo = _s(inp.get("line_of_business")).upper()
    sum_insured = _dec(inp.get("sum_insured"))
    ded_type = _s(inp.get("deductible_type")).upper()
    ded_value = _dec(inp.get("deductible_value"))
    pending_premium = _dec(inp.get("pending_premium"))
    category = _s(inp.get("customer_category")).upper()
    coverage_found = _bool(inp.get("coverage_found"))
    cov_limit = _dec(inp.get("coverage_limit"))
    cov_pct = _dec(inp.get("coverage_percentage"))
    waiting_days = _dec(inp.get("waiting_days"))
    prior_count = _dec(inp.get("prior_liquidated_claims_365d"))
    total_indemnified = _dec(inp.get("total_indemnified"))
    if prior_count is None:
        prior_count = Decimal(0)  # COUNT(*) nunca es NULL
    if total_indemnified is None:
        total_indemnified = Decimal(0)  # NVL(SUM(...),0)

    def reject(reason, obs=None):
        return {
            "base_amount": "0.00",
            "deductible_amount": "0.00",
            "covered_amount": "0.00",
            "withholding_amount": "0.00",
            "net_amount": "0.00",
            "liquidation_status": "RECHAZADA",
            "reason_code": reason,
            "observations": obs or "",
            "claim_new_status": "RECHAZADO",
            "error_code": "",
        }

    # Lectura inicial (línea 375): fuerza ORA-20010 si falta el parámetro
    p("FACTOR_INFLACION")

    obs = None

    # 1.a Estado de la póliza
    if policy_status != "VIGENTE":
        return reject("POLIZA_NO_VIGENTE")

    # 1.b Vigencia (extremos inclusive)
    if occ < pol_start or occ > pol_end:
        return reject("FUERA_DE_VIGENCIA")

    # 1.c Plazo de denuncia
    dias_denuncia = Decimal(rep - occ)
    if ramo == "VIDA":
        dias_max = p("DIAS_MAX_DENUNCIA_VIDA")
    else:
        dias_max = p("DIAS_MAX_DENUNCIA")
    if _gt(dias_denuncia, dias_max):
        return reject("DENUNCIA_EXTEMPORANEA")

    # 1.d Cobertura contratada
    if not coverage_found:
        return reject("COBERTURA_NO_CONTRATADA")

    # 1.e Carencia
    dias_desde_inicio = Decimal(occ - pol_start)
    if _lt(dias_desde_inicio, waiting_days):
        return reject("EN_PERIODO_CARENCIA")

    # 1.f Morosidad
    if _gt(pending_premium, Decimal(0)):
        tolerancia = p("TOLERANCIA_MORA_VIP")
        if category == "VIP" and _le(pending_premium, tolerancia):
            obs = _add_obs(obs, "TOLERANCIA_MORA_VIP")
        else:
            return reject("PRIMA_EN_MORA", obs)

    # 2.a Monto base
    if _gt(claimed, cov_limit):
        base = _store_14_2(cov_limit)
        obs = _add_obs(obs, "LIMITE_COBERTURA")
    else:
        base = _store_14_2(claimed)

    # 2.b Deducible (fn_calcular_deducible, v_deducible NUMBER(14,2))
    if ded_type == "FIJO":
        ded = _store_14_2(ded_value)
    else:
        ded_min = p("DEDUCIBLE_MINIMO")
        ded = _store_14_2(_round2(_div(_mul(base, ded_value), Decimal(100))))
        if _lt(ded, ded_min):
            ded = _store_14_2(ded_min)
            obs = _add_obs(obs, "DEDUCIBLE_MINIMO")
    if category == "VIP" and _gt(ded, Decimal(0)):
        pct_vip = p("PCT_DESCUENTO_DED_VIP")
        ded = _store_14_2(_round2(_div(_mul(ded, _sub(Decimal(100), pct_vip)), Decimal(100))))
        obs = _add_obs(obs, "DESCUENTO_VIP")
    ded = _store_14_2(ded)

    # 2.c Monto cubierto
    cub = _store_14_2(_round2(_div(_mul(_sub(base, ded), cov_pct), Decimal(100))))
    if _le(cub, Decimal(0)):
        return reject("BAJO_DEDUCIBLE", obs)

    # 2.d Siniestralidad
    if _ge(prior_count, p("MAX_SINIESTROS_ANUAL")):
        pen = p("PCT_PENALIZACION_SINIEST")
        cub = _store_14_2(_round2(_div(_mul(cub, _sub(Decimal(100), pen)), Decimal(100))))
        obs = _add_obs(obs, "PENALIZACION_SINIESTRALIDAD")

    # 2.e Suma asegurada remanente
    remanente = _sub(sum_insured, total_indemnified)
    if _le(remanente, Decimal(0)):
        return reject("SUMA_ASEGURADA_AGOTADA", obs)
    if _gt(cub, remanente):
        cub = _store_14_2(remanente)
        obs = _add_obs(obs, "TOPE_SUMA_ASEGURADA")

    # 2.f Retención y neto
    if ramo != "VIDA" and ramo != "" and _gt(cub, p("UMBRAL_RETENCION")):
        ret = _store_14_2(_round2(_div(_mul(cub, p("TASA_RETENCION")), Decimal(100))))
        obs = _add_obs(obs, "RETENCION_APLICADA")
    else:
        ret = Decimal("0.00")
    neto = _store_14_2(_sub(cub, ret))

    # 3. Estado final
    umbral_fraude = _round2(_div(_mul(cov_limit, p("PCT_ALERTA_FRAUDE")), Decimal(100)))
    if _le(dias_desde_inicio, p("DIAS_ALERTA_FRAUDE")) and _ge(claimed, umbral_fraude):
        estado, motivo = "PENDIENTE_APROBACION", "SOSPECHA_FRAUDE"
    elif _gt(neto, p("TOPE_AUTO_APROBACION")):
        estado, motivo = "PENDIENTE_APROBACION", "SUPERA_TOPE_AUTOMATICO"
    else:
        estado, motivo = "APROBADA", "LIQUIDACION_AUTOMATICA"

    claim_new = {
        "APROBADA": "LIQUIDADO",
        "RECHAZADA": "RECHAZADO",
        "PENDIENTE_APROBACION": "PENDIENTE_REVISION",
    }[estado]

    return {
        "base_amount": _fmt2(base),
        "deductible_amount": _fmt2(ded),
        "covered_amount": _fmt2(cub),
        "withholding_amount": _fmt2(ret),
        "net_amount": _fmt2(neto),
        "liquidation_status": estado,
        "reason_code": motivo,
        "observations": obs or "",
        "claim_new_status": claim_new,
        "error_code": "",
    }
